import { useState } from 'react';
import './dashboard.css';

function Dashboard({ userName, onLogout }) {
  const [tasks, setTasks] = useState([
    { id: 1, title: "Plan today's tasks", category: 'Personal', done: true },
    { id: 2, title: 'Complete project work', category: 'Work', done: false },
    { id: 3, title: 'Review your progress', category: 'Personal', done: false },
  ]);
  const [newTask, setNewTask] = useState('');

  function toggleTask(id) {
    setTasks(tasks.map((task) => (
      task.id === id ? { ...task, done: !task.done } : task
    )));
  }

  function addTask(event) {
    event.preventDefault();
    if (!newTask.trim()) return;
    setTasks([...tasks, { id: Date.now(), title: newTask.trim(), category: 'Personal', done: false }]);
    setNewTask('');
  }

  const completedTasks = tasks.filter((task) => task.done).length;
  const firstLetter = userName.charAt(0).toUpperCase();

  return (
    <main className="dashboard-page">
      <aside className="dashboard-sidebar">
        <h1 className="dashboard-logo">Task Manager</h1>
        <nav aria-label="Main navigation">
          <button className="nav-item active" type="button">Dashboard</button>
          <button className="nav-item" type="button">My Tasks</button>
          <button className="nav-item" type="button">Settings</button>
        </nav>
        <button className="sidebar-logout" type="button" onClick={onLogout}>Logout</button>
      </aside>

      <section className="dashboard-main">
        <header className="dashboard-topbar">
          <div>
            <p className="dashboard-label">Dashboard</p>
            <h2>Welcome, {userName}!</h2>
          </div>
          <div className="user-profile" title={`Signed in as ${userName}`}>
            <span className="user-avatar">{firstLetter}</span>
            <span>{userName}</span>
          </div>
        </header>

        <p className="dashboard-intro">Here is what you have planned for today.</p>

        <section className="stats-grid" aria-label="Task summary">
          <article className="stat-card"><span>Total Tasks</span><strong>{tasks.length}</strong></article>
          <article className="stat-card"><span>Completed</span><strong>{completedTasks}</strong></article>
          <article className="stat-card"><span>Remaining</span><strong>{tasks.length - completedTasks}</strong></article>
        </section>

        <section className="dashboard-grid">
          <section className="tasks-box" aria-labelledby="tasks-title">
            <div className="section-heading">
              <div><p className="section-label">For today</p><h3 id="tasks-title">My Tasks</h3></div>
              <span>{completedTasks}/{tasks.length}</span>
            </div>
            <form className="add-task-form" onSubmit={addTask}>
              <input value={newTask} onChange={(event) => setNewTask(event.target.value)} placeholder="Add a new task" aria-label="New task" />
              <button type="submit">Add</button>
            </form>
            <div className="task-list">
              {tasks.map((task) => (
                <label className={`task-item ${task.done ? 'completed' : ''}`} key={task.id}>
                  <input type="checkbox" checked={task.done} onChange={() => toggleTask(task.id)} />
                  <span className="task-name">{task.title}<small>{task.category}</small></span>
                </label>
              ))}
            </div>
          </section>

          <section className="progress-box" aria-labelledby="progress-title">
            <p className="section-label">Your progress</p>
            <h3 id="progress-title">Today&apos;s progress</h3>
            <div className="progress-circle"><strong>{tasks.length ? Math.round((completedTasks / tasks.length) * 100) : 0}%</strong></div>
            <p>{completedTasks === tasks.length ? 'All tasks completed!' : 'Keep going, you are doing well.'}</p>
          </section>
        </section>
      </section>
    </main>
  );
}

export default Dashboard;
